import { Component, Prop, Element, ComponentInterface } from '@stencil/core';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { BtnHTMLType, BtnSize, BtnVariant } from './types';
import { BaseButton } from './base';
import { sendActionTracking } from '@src/shared/unclassified/tracking';

/**
 * @slot default - Icon or custom content rendered inside the icon button.
 * @part base - The base container of the component.
 */
@Component({
  tag: 'ks-icon-button',
  styleUrl: 'base.scss',
  shadow: true,
})
export class KsIconButton implements ComponentInterface {
  @Element() el!: HTMLKsIconButtonElement;

  /** The variant of the button, representing its type. Can be one of the following values: `"default"`, `"primary"`, `"secondary"`, `"filled"`, `"tertiary"`, `"text"`, `"inverse"`, `"inline"` or `"alert"`. */
  @Prop() variant: BtnVariant = 'default';
  /** The size of the button. Can be one of the following values: `"xs"`, `"sm"`, `"md"` or `"lg"`. */
  @Prop() size: BtnSize = 'md';
  /** Indicates whether the button is disabled. If set to `true`, the button will be un-clickable and visually indicate its disabled state. */
  @Prop() disabled = false;
  /** Indicates whether the button is in a loading state. If set to `true`, a loading indicator will be displayed on the button, preventing user interaction until the loading is complete. */
  @Prop() loading = false;
  /** Sets the `type` attribute of the button element. This determines the button's behavior in forms and can be one of the following values: `"button"`, `"submit"` or `"reset"`. */
  @Prop() htmlType: BtnHTMLType = 'button';

  /** Force the button to stay in active style. */
  @Prop() forceActive = false;

  constructor() {
    registerPluginManager(this.el);
  }

  private sendClickTracking = () => {
    sendActionTracking(this.el, { eventType: 'click' });
  };

  render() {
    return BaseButton({
      iconOnly: true,
      el: this.el,
      variant: this.variant,
      size: this.size,
      disabled: this.disabled,
      loading: this.loading,
      htmlType: this.htmlType,
      forceActive: this.forceActive,
      sendClickTracking: this.sendClickTracking,
    });
  }
}
